local releases = {
    ["3.2a"] = catalogs.c1,
    ["3.3"] = catalogs.c2,
    ["3.3a"] = catalogs.c2,
    ["3.4"] = catalogs.c3,
    ["3.5"] = catalogs.c4,
    ["3.5a"] = catalogs.c4,
    ["3.6"] = catalogs.c5,
    ["3.6a"] = catalogs.c5,
    ["3.6b"] = catalogs.c5,
    ["3.7"] = catalogs.c6,
    ["3.7a"] = catalogs.c6,
    ["3.7b"] = catalogs.c6,
    ["3.7c"] = catalogs.c6,
}

local function copy(value)
    if type(value) ~= "table" then
        return value
    end
    local result = {}
    for key, item in pairs(value) do
        result[key] = copy(item)
    end
    return result
end

local function release(version)
    if type(version) ~= "string" or releases[version] == nil then
        return nil,
            errors.new(
                "unsupported_version",
                "option catalog needs an explicitly cataloged tmux release"
            )
    end
    return releases[version]
end

---@param version string
---@param name string
---@return libtmux.OptionDescriptor? descriptor
---@return libtmux.Error? error
function M.lookup(version, name)
    local entries, err = release(version)
    if not entries then
        return nil, err
    end
    local key = type(name) == "string" and entries[name] or nil
    if key == nil then
        return nil,
            errors.new(
                "unknown_option",
                "option catalog needs a canonical built-in name for this release"
            )
    end
    return copy(definitions[key])
end

---@param version string
---@param family? 'option'|'hook'
---@return string[]? names
---@return libtmux.Error? error
function M.names(version, family)
    local entries, err = release(version)
    if not entries then
        return nil, err
    end
    if family ~= nil and family ~= "option" and family ~= "hook" then
        return nil, errors.new("invalid_family", "option catalog family must be option or hook")
    end
    local names = {}
    for name, key in pairs(entries) do
        local hook = definitions[key].hook
        if family == nil or (family == "hook" and hook) or (family == "option" and not hook) then
            names[#names + 1] = name
        end
    end
    table.sort(names)
    return names
end

return M
